from pathlib import Path
p=Path('main_base.py')
s=p.read_text(encoding='utf-8')
# imports for fully custom drawn widgets
s=s.replace('from kivy.graphics import Color, Rectangle','from kivy.graphics import Color, Rectangle, RoundedRectangle, Line')
insert='''\nclass CarbonPanel(BoxLayout):\n    def __init__(self, **kw):\n        super().__init__(**kw)\n        with self.canvas.before:\n            Color(.025,.028,.032,1); self.bg=RoundedRectangle(pos=self.pos,size=self.size,radius=[dp(10)])\n            Color(.20,.21,.22,1); self.edge=Line(rounded_rectangle=(self.x,self.y,self.width,self.height,dp(10)),width=1.2)\n            Color(.34,.02,.02,.45); self.rededge=Line(rounded_rectangle=(self.x+dp(2),self.y+dp(2),max(0,self.width-dp(4)),max(0,self.height-dp(4)),dp(8)),width=.8)\n        self.bind(pos=self._sync,size=self._sync)\n    def _sync(self,*_):\n        self.bg.pos=self.pos; self.bg.size=self.size\n        self.edge.rounded_rectangle=(self.x,self.y,self.width,self.height,dp(10))\n        self.rededge.rounded_rectangle=(self.x+dp(2),self.y+dp(2),max(0,self.width-dp(4)),max(0,self.height-dp(4)),dp(8))\n\nclass CarbonButton(Button):\n    def __init__(self, active=False, **kw):\n        super().__init__(background_normal='',background_down='',background_color=(0,0,0,0),color=(.94,.94,.94,1),**kw)\n        self.active=active\n        with self.canvas.before:\n            Color(.055,.06,.065,1); self.bg=RoundedRectangle(pos=self.pos,size=self.size,radius=[dp(7)])\n            self.rc=Color(1,.08,.04,.9 if active else .5); self.line=Line(rounded_rectangle=(self.x,self.y,self.width,self.height,dp(7)),width=1.5 if active else 1.0)\n        self.bind(pos=self._sync,size=self._sync,state=self._state)\n    def _sync(self,*_): self.bg.pos=self.pos; self.bg.size=self.size; self.line.rounded_rectangle=(self.x,self.y,self.width,self.height,dp(7))\n    def _state(self,*_): self.rc.a=1 if self.state=='down' or self.active else .5\n\nclass CarbonHexRow(BoxLayout):\n    def __init__(self, **kw):\n        super().__init__(orientation='horizontal',spacing=dp(2),padding=dp(3),**kw)\n        with self.canvas.before:\n            Color(.045,.05,.055,1); self.bg=RoundedRectangle(pos=self.pos,size=self.size,radius=[dp(5)])\n            Color(.23,.24,.25,1); self.l=Line(rounded_rectangle=(self.x,self.y,self.width,self.height,dp(5)),width=1)\n        self.bind(pos=self._sync,size=self._sync)\n    def _sync(self,*_): self.bg.pos=self.pos;self.bg.size=self.size;self.l.rounded_rectangle=(self.x,self.y,self.width,self.height,dp(5))\n'''
s=s.replace('class Main(BoxLayout):',insert+'\nclass Main(BoxLayout):')
# blue changed hex
s=s.replace('[color=ff3333]','[color=00A8FF]')
# Entire Main UI constructor replaced while retaining functional methods below it
start=s.index('    def __init__(self,**kw):',s.index('class Main(BoxLayout):'))
