new='''    def __init__(self,**kw):\n        super().__init__(orientation="vertical",spacing=dp(7),padding=dp(10),**kw)\n        self.app=App.get_running_app(); self.module="IC"; self.status=self.app.data.get("ui",{}).get("ready_text","Готово"); self.changed={}; self.checks={}; self._syncing=False\n        with self.canvas.before:\n            Color(.012,.014,.016,1); self.carbon=Rectangle(pos=self.pos,size=self.size)\n        self.bind(pos=lambda *_:setattr(self.carbon,"pos",self.pos),size=lambda *_:setattr(self.carbon,"size",self.size))\n        top=CarbonPanel(size_hint_y=None,height=dp(62),padding=dp(8),spacing=dp(8))\n        brand=Label(text="[b]MAZDA 6 GH[/b]\\n[color=aaaaaa]AS BUILT STUDIO[/color]",markup=True,font_size="16sp",halign="left",valign="middle");brand.bind(size=lambda w,v:setattr(w,"text_size",v));top.add_widget(brand)\n        info=CarbonButton(text="ⓘ",font_size="24sp",size_hint_x=None,width=dp(58));info.bind(on_release=self.show_about);top.add_widget(info)\n        admin=CarbonButton(text="⚙",font_size="22sp",size_hint_x=None,width=dp(58));admin.bind(on_release=self.admin_login);top.add_widget(admin);self.add_widget(top)\n        self.tabholder=BoxLayout(size_hint_y=None,height=dp(52),spacing=dp(5));self.add_widget(self.tabholder)\n        self.body=CarbonPanel(orientation="vertical",padding=dp(9),spacing=dp(7));self.add_widget(self.body)\n        actions=BoxLayout(size_hint_y=None,height=dp(58),spacing=dp(8));ob=CarbonButton(text=self.app.data.get("ui",{}).get("open_text","OPEN AS-BUILT"),font_size="15sp");sb=CarbonButton(text=self.app.data.get("ui",{}).get("save_text","SAVE AS-BUILT"),font_size="15sp");ob.bind(on_release=self.open_abt);sb.bind(on_release=self.save_abt);actions.add_widget(ob);actions.add_widget(sb);self.add_widget(actions)\n        self.stat=Label(text=self.status,size_hint_y=None,height=dp(27),font_size="11sp",color=(.72,.72,.72,1));self.add_widget(self.stat);self.refresh()\n\n    def refresh(self):\n        self.tabholder.clear_widgets()\n        for m in self.app.data.get("modules",[]):\n            mid=m.get("id","IC");b=CarbonButton(text=mid,active=(mid==self.module),font_size="14sp");b.bind(on_release=lambda x,mm=mid:self.switch_module(mm));self.tabholder.add_widget(b)\n        self.body.clear_widgets(); mod=next((m for m in self.app.data.get("modules",[]) if m.get("id")==self.module),{})\n        hdr=Label(text=f'[b]{mod.get("name",self.module)}[/b]   [color=999999]| {mod.get("address","")} | {mod.get("version","")}[/color]',markup=True,size_hint_y=None,height=dp(48),halign="left",valign="middle");hdr.bind(size=lambda w,v:setattr(w,"text_size",v));self.body.add_widget(hdr)\n        feats=[f for f in self.app.data.get("features",[]) if f.get("module")==self.module];fg=GridLayout(cols=max(1,int(self.app.data.get("ui",{}).get("feature_columns",2))),spacing=dp(5),size_hint_y=None);fg.bind(minimum_height=fg.setter("height"));self.checks={}\n        for f in feats:\n            tile=CarbonPanel(size_hint_y=None,height=dp(58),padding=(dp(6),dp(3)),spacing=dp(5));cb=CheckBox(size_hint_x=None,width=dp(38));lab=Label(text=f.get("label",""),halign="left",valign="middle",font_size="12sp");lab.bind(size=lambda w,v:setattr(w,"text_size",v));tile.add_widget(cb);tile.add_widget(lab);fg.add_widget(tile);self.checks[f.get("id")]=cb;cb.bind(active=lambda c,v,ff=f:self.feature_toggle(ff,v))\n        self.body.add_widget(fg)\n        self.rowsbox=GridLayout(cols=1,spacing=dp(5),size_hint_y=None);self.rowsbox.bind(minimum_height=self.rowsbox.setter("height"));sc=ScrollView();sc.add_widget(self.rowsbox);self.body.add_widget(sc);self.render_rows();self.sync_feature_checks()\n\n    def render_rows(self):\n        if not hasattr(self,"rowsbox"): return\n        self.rowsbox.clear_widgets()\n        for r in [x for x in self.app.data.get("rows",[]) if x.get("module")==self.module]:\n            row=CarbonHexRow(size_hint_y=None,height=dp(57));a=Label(text='[b]'+r.get("address","")+'[/b]',markup=True,size_hint_x=.35,font_size="14sp",color=(.8,.8,.8,1));raw=norm(r.get("value",""));pos=self.changed.get(r.get("address"),set());rendered='';\n            for i,ch in enumerate(raw): rendered += (f'[color=00A8FF][b]{ch}[/b][/color]' if i in pos else ch)\n            chunks=' '.join(rendered[i:i+4] for i in range(0,len(rendered),4)) if not pos else rendered\n            v=Label(text=chunks,markup=True,font_size="15sp",color=(.92,.92,.92,1));row.add_widget(a);row.add_widget(v);self.rowsbox.add_widget(row)\n\n'''
s=s[:start]+new+s[end:]
